"use client";

import * as React from "react";
import styles from "../styles/grid-pulse.module.css";

export interface GridPulseProps {
  /** Number of grid columns */
  cols?: number;
  /** Number of grid rows */
  rows?: number;
  /** Cell pulse color */
  pulseColor?: string;
  /** Pulse cycle duration in seconds */
  duration?: number;
  /** Foreground content rendered above the grid */
  children?: React.ReactNode;
  /** Optional className merged onto the root */
  className?: string;
}

const rand = (n: number) => {
  const x = Math.sin(n * 9301 + 49297) * 233280;
  return x - Math.floor(x);
};

export function GridPulse({
  cols = 12,
  rows = 6,
  pulseColor = "#38bdf8",
  duration = 3,
  children,
  className = "",
}: GridPulseProps) {
  const c = Math.max(1, Math.round(cols));
  const r = Math.max(1, Math.round(rows));
  const styleVars = {
    "--mf-gp-color": pulseColor,
    "--mf-gp-duration": `${duration > 0 ? duration : 3}s`,
    "--mf-gp-cols": c,
    "--mf-gp-rows": r,
  } as React.CSSProperties;

  return (
    <div style={styleVars} className={`${styles.root} ${className}`.trim()}>
      <div aria-hidden="true" className={styles.grid}>
        {Array.from({ length: c * r }, (_, i) => (
          <span
            key={i}
            className={styles.cell}
            style={{ "--mf-gp-delay": `-${(rand(i) * 6).toFixed(2)}s` } as React.CSSProperties}
          />
        ))}
      </div>
      <div className={styles.content}>
        {children ?? (
          <div className={styles.copy}>
            <h3 className={styles.title}>Grid Pulse</h3>
            <p className={styles.subtitle}>
              {c} × {r} cells, CSS-only
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

.root {
  position: relative;
  overflow: hidden;
  display: flex;
  width: 100%;
  min-height: 18rem;
  border-radius: 1rem;
  border: 1px solid var(--mf-border, #2e2e38);
  background-color: var(--mf-bg, #09090b);
  color: var(--mf-fg, #f4f4f6);
}

.grid {
  position: absolute;
  inset: 0;
  display: grid;
  grid-template-columns: repeat(var(--mf-gp-cols, 12), 1fr);
  grid-template-rows: repeat(var(--mf-gp-rows, 6), 1fr);
  pointer-events: none;
  mask-image: radial-gradient(ellipse at center, black 35%, transparent 85%);
}

.cell {
  position: relative;
  border-right: 1px solid rgba(46, 46, 56, 0.55);
  border-bottom: 1px solid rgba(46, 46, 56, 0.55);
}

.cell::after {
  content: "";
  position: absolute;
  inset: 0;
  background-color: var(--mf-gp-color, var(--mf-accent, #38bdf8));
  opacity: 0;
  animation: mfGridPulse var(--mf-gp-duration, 3s) ease-in-out infinite;
  animation-delay: var(--mf-gp-delay, 0s);
  will-change: opacity;
}

.content {
  position: relative;
  z-index: 1;
  display: flex;
  flex: 1;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}

.copy {
  text-align: center;
}

.title {
  margin: 0;
  font-size: 1.75rem;
  font-weight: 600;
  letter-spacing: -0.03em;
}

.subtitle {
  margin: 0.5rem 0 0;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.78rem;
  color: var(--mf-muted, #a1a1aa);
}

@keyframes mfGridPulse {
  0%,
  50% {
    opacity: 0;
  }
  70% {
    opacity: 0.45;
  }
  100% {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cell::after {
    animation: none;
    opacity: 0;
  }
}

