"use client";

import { motion } from "motion/react";

const rand = (n: number) => { const x = Math.sin(n * 9301 + 49297) * 233280; return x - Math.floor(x); };

export function GridPulseTailwind({ cols = 12, rows = 6 }) {
  return (
    <div className="relative flex min-h-72 w-full items-center justify-center overflow-hidden rounded-2xl border border-zinc-800 bg-zinc-950">
      <div aria-hidden className="absolute inset-0 grid" style={{ gridTemplateColumns: `repeat(${cols},1fr)`, gridTemplateRows: `repeat(${rows},1fr)` }}>
        {Array.from({ length: cols * rows }, (_, i) => (
          <div key={i} className="border-b border-r border-zinc-800/60">
            <motion.div
              className="h-full w-full bg-sky-400"
              initial={{ opacity: 0 }}
              animate={{ opacity: [0, 0, 0.45, 0] }}
              transition={{ duration: 3, repeat: Infinity, delay: rand(i) * 6, times: [0, 0.5, 0.7, 1] }}
            />
          </div>
        ))}
      </div>
      <h3 className="relative z-10 text-2xl font-semibold text-zinc-100">Grid Pulse</h3>
    </div>
  );
}
